import java.util.*;

class Solution {
    public List<List<String>> partition(String s) {
        List<List<String>> answer = new ArrayList<>();
        backtrack(s, 0, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(String s, int start, List<String> path, List<List<String>> answer) {
        if (start == s.length()) {
            answer.add(new ArrayList<>(path));
            return;
        }
        for (int end = start; end < s.length(); end++) {
            if (!isPalindrome(s, start, end)) {
                continue;
            }
            path.add(s.substring(start, end + 1));
            backtrack(s, end + 1, path, answer);
            path.remove(path.size() - 1);
        }
    }

    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left++) != s.charAt(right--)) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public List<List<String>> partition(String s) {
        boolean[][] palindrome = buildPalindromeTable(s);
        List<List<String>> answer = new ArrayList<>();
        backtrack(s, 0, palindrome, new ArrayList<>(), answer);
        return answer;
    }

    private void backtrack(String s, int start, boolean[][] palindrome,
                           List<String> path, List<List<String>> answer) {
        if (start == s.length()) {
            answer.add(new ArrayList<>(path));
            return;
        }
        for (int end = start; end < s.length(); end++) {
            if (!palindrome[start][end]) {
                continue;
            }
            path.add(s.substring(start, end + 1));
            backtrack(s, end + 1, palindrome, path, answer);
            path.remove(path.size() - 1);
        }
    }

    private boolean[][] buildPalindromeTable(String s) {
        int n = s.length();
        boolean[][] palindrome = new boolean[n][n];
        for (int start = n - 1; start >= 0; start--) {
            for (int end = start; end < n; end++) {
                palindrome[start][end] = s.charAt(start) == s.charAt(end)
                        && (end - start < 2 || palindrome[start + 1][end - 1]);
            }
        }
        return palindrome;
    }
}

import java.util.*;

class Solution {
    private static class State {
        final int start;
        final List<String> path;

        State(int start, List<String> path) {
            this.start = start;
            this.path = path;
        }
    }

    public List<List<String>> partition(String s) {
        List<List<String>> answer = new ArrayList<>();
        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(0, new ArrayList<>()));

        while (!stack.isEmpty()) {
            State state = stack.pop();
            if (state.start == s.length()) {
                answer.add(state.path);
                continue;
            }
            for (int end = s.length() - 1; end >= state.start; end--) {
                if (!isPalindrome(s, state.start, end)) {
                    continue;
                }
                List<String> next = new ArrayList<>(state.path);
                next.add(s.substring(state.start, end + 1));
                stack.push(new State(end + 1, next));
            }
        }
        return answer;
    }

    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left++) != s.charAt(right--)) {
                return false;
            }
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public List<List<String>> partition(String s) {
        int n = s.length();
        boolean[][] palindrome = buildPalindromeTable(s);
        List<List<List<String>>> suffixPartitions = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            suffixPartitions.add(new ArrayList<>());
        }
        suffixPartitions.get(n).add(new ArrayList<>());

        for (int start = n - 1; start >= 0; start--) {
            for (int end = start; end < n; end++) {
                if (!palindrome[start][end]) {
                    continue;
                }
                String first = s.substring(start, end + 1);
                for (List<String> suffix : suffixPartitions.get(end + 1)) {
                    List<String> partition = new ArrayList<>();
                    partition.add(first);
                    partition.addAll(suffix);
                    suffixPartitions.get(start).add(partition);
                }
            }
        }
        return suffixPartitions.get(0);
    }

    private boolean[][] buildPalindromeTable(String s) {
        int n = s.length();
        boolean[][] palindrome = new boolean[n][n];
        for (int start = n - 1; start >= 0; start--) {
            for (int end = start; end < n; end++) {
                palindrome[start][end] = s.charAt(start) == s.charAt(end)
                        && (end - start < 2 || palindrome[start + 1][end - 1]);
            }
        }
        return palindrome;
    }
}
